import type { EventSurfaceProps } from './EventSurfaceRenderer'

type AsyncState = 'loading' | 'ready' | 'empty' | 'error' | 'permission-denied' | 'conflict'
const surfaceStatusSummary = (state: AsyncState, language: 'en' | 'zh') => {
  const labels: Partial<Record<AsyncState, string>> = language === 'zh'
    ? { ...eventOperationsSurfacesText.localizedCopy.zh }
    : { ...eventOperationsSurfacesText.localizedCopy.en }
  return labels[state]
}
const fieldClass = 'min-h-11 min-w-0 w-full rounded-xl border border-[#2f4b42]/20 bg-white px-3 text-sm text-[#18332d] outline-none focus:border-[#176b5a] focus:ring-2 focus:ring-[#176b5a]/15'
const labelClass = 'grid min-w-0 gap-1.5 text-xs font-bold uppercase tracking-[0.08em] text-[#66766f]'
const localize = (value: { en: string; zh: string }, language: 'en' | 'zh') => value[language] || value.en || value.zh
const fromLocalInput = (value: string) => new Date(value).toISOString()

const resolveState = (error: unknown): AsyncState => {
  const value = normalizeApiError(error)
  if (value.status === 403) return 'permission-denied'
  if (value.status === 409 || value.status === 412) return 'conflict'
  return 'error'
}

const SurfaceState = ({ state, language, error, onRetry }: { state: AsyncState; language: 'en' | 'zh'; error: string; onRetry: () => void }) => {
  if (state === 'loading') return <p className="text-sm text-[#66766f]" role="status">{language === 'zh' ? eventOperationsSurfacesText.loading.zh : eventOperationsSurfacesText.loading.en}</p>
  if (state === 'permission-denied') return <AppEmptyState title={language === 'zh' ? eventOperationsSurfacesText.accessRequired.zh : eventOperationsSurfacesText.accessRequired.en} description={language === 'zh' ? eventOperationsSurfacesText.thisDataIsLimitedToAcceptedEventTeamMembers.zh : eventOperationsSurfacesText.thisDataIsLimitedToAcceptedEventTeamMembers.en} />
  if (state === 'error' || state === 'conflict') return <AppEmptyState title={state === 'conflict' ? (language === 'zh' ? eventOperationsSurfacesText.dataChanged.zh : eventOperationsSurfacesText.dataChanged.en) : (language === 'zh' ? eventOperationsSurfacesText.unableToLoad.zh : eventOperationsSurfacesText.unableToLoad.en)} description={error} actionLabel={language === 'zh' ? eventOperationsSurfacesText.reload.zh : eventOperationsSurfacesText.reload.en} onAction={onRetry} />
  return null
}

export const EventTeamPanel = ({ eventId, groupId, language, item, onBusyChange, onSaved, setupFlow, moduleSelections, planRevision, canManage }: EventSurfaceProps) => {
  const currentMemberId = useAuthStore().me?.id
  const [data, setData] = useState<EventTeamWorkspace | null>(null)
  const [candidates, setCandidates] = useState<MemberSummaryDto[]>([])
  const [state, setState] = useState<AsyncState>('loading')
  const [error, setError] = useState('')
  const [inviteeId, setInviteeId] = useState('')


  const [taskTitleEn, setTaskTitleEn] = useState('')
  const [taskTitleZh, setTaskTitleZh] = useState('')
  const [taskDescription, setTaskDescription] = useState({ en: '', zh: '' })
  const [taskPage, setTaskPage] = useState(1), [taskSort, setTaskSort] = useState('due'), [filterStatus, setFilterStatus] = useState('all')
  const [taskDue, setTaskDue] = useState('')
  const [taskParams] = useSearchParams()
  const [taskStage, setTaskStage] = useState(taskParams.get('taskStage') || 'preparation'), [taskOccurrence, setTaskOccurrence] = useState(taskParams.get('occurrenceId') || ''), [filterStage, setFilterStage] = useState(taskParams.get('taskStage') || 'all'), [taskOccurrences, setTaskOccurrences] = useState<EventOccurrence[]>([])
  useEffect(() => { let live = true; void eventOperationsService.listOccurrences(eventId).then(rows => { if (live) setTaskOccurrences(rows) }).catch(() => {}); return () => { live = false } }, [eventId])
  const [activityPlan, setActivityPlan] = useState<ActivityPlanData | null>(null), [taskActivity, setTaskActivity] = useState('')
  const [eventContext, setEventContext] = useState<FormAssistantContext>()
  useEffect(() => {
    if (!currentMemberId) return
    let live = true
    void eventService.getGroupEvents(groupId, currentMemberId).then(records => {
      if (!live) return
      const record = records.find(item => item.id === eventId)
      let details: { title?: Bilingual; description?: Bilingual } = {}
      try { details = record?.eventDataJson ? JSON.parse(record.eventDataJson) as typeof details : {} } catch { details = {} }
      setEventContext({ eventTitle: details.title || { en: record?.titleEn || '', zh: record?.titleZh || '' }, eventDescription: details.description || { en: '', zh: '' } })
    }).catch(() => {})
    return () => { live = false }
  }, [eventId, groupId, currentMemberId])
  const [assigneeId, setAssigneeId] = useState('')
  const [requiresApproval, setRequiresApproval] = useState(false)
  const [reviewerId, setReviewerId] = useState('')
  const [isRestricted, setIsRestricted] = useState(false)
  const [busy, setBusy] = useState(false), [aiBusy, setAiBusy] = useState(false)
  const teamRequest = useRef(0)

  useArrangementDraft(Boolean(inviteeId || taskTitleEn || taskTitleZh || taskDescription.en || taskDescription.zh || taskDue || assigneeId || requiresApproval || isRestricted))
  const load = useCallback(async () => {
    const version = ++teamRequest.current
    setState('loading'); setError('')
    try {
      const next = await eventOperationsService.getTeam(eventId)
      if (version !== teamRequest.current) return
      setData(next); setState(next.members.length || next.tasks.length || next.roles.length ? 'ready' : 'empty')
      if (next.canManage) {
        const memberships = await groupService.getGroupMemberships(groupId)
        if (version !== teamRequest.current) return
        setCandidates(memberships.filter((membership) => membership.status === 'approved').map((membership) => ({ id: membership.memberId, displayName: membership.displayName ?? null })))
      }
    } catch (reason) { if (version === teamRequest.current) { setState(resolveState(reason)); setError(normalizeApiError(reason).message) } }
  }, [eventId, groupId, currentMemberId, planRevision])

  useEffect(() => { setData(null); setCandidates([]); void load(); return () => { teamRequest.current++ } }, [load])
  useEffect(() => { onBusyChange?.(busy || aiBusy) }, [busy, aiBusy, onBusyChange])

  const mutate = async (action: () => Promise<unknown>) => {
    setBusy(true); setError('')
    try { await action(); await load(); await onSaved?.() } catch (reason) { setState(resolveState(reason)); setError(normalizeApiError(reason).message) } finally { setBusy(false) }
  }

  const createTask = (event: FormEvent) => {
    event.preventDefault()
    if (busy || aiBusy || !canManage || !taskTitleEn.trim() || !taskTitleZh.trim()) return
    void mutate(async () => {
      await eventOperationsService.createTask(eventId, { title: { en: taskTitleEn.trim(), zh: taskTitleZh.trim() }, description: taskDescription, activityId: taskActivity || null, requireAcceptance: true, assignedMemberId: assigneeId || null, dueUtc: taskDue ? fromLocalInput(taskDue) : null, isRequired: true, requiresApproval, isRestricted, reviewerMemberId: reviewerId || null, stage: taskStage, eventOccurrenceId: taskOccurrence || null })
      setTaskActivity(''); setTaskTitleEn(''); setTaskTitleZh(''); setTaskDescription({ en: '', zh: '' }); setTaskDue(''); setAssigneeId(''); setRequiresApproval(false); setIsRestricted(false); setReviewerId('')
    })
  }

  const taskColumns: Array<{ status: EventTaskStatus; en: string; zh: string }> = [
    { status: 'todo', en: eventOperationsSurfacesText.todo.en, zh: eventOperationsSurfacesText.todo.zh }, { status: 'inProgress', en: eventOperationsSurfacesText.inProgress.en, zh: eventOperationsSurfacesText.inProgress.zh },
    { status: 'blocked', en: eventOperationsSurfacesText.blocked.en, zh: eventOperationsSurfacesText.blocked.zh }, { status: 'done', en: eventOperationsSurfacesText.done.en, zh: eventOperationsSurfacesText.done.zh },
    { status: 'cancelled', en: eventOperationsSurfacesText.cancelled.en, zh: eventOperationsSurfacesText.cancelled.zh },
  ]
  const taskRows = (data?.tasks ?? []).filter(task => (filterStage === 'all' || (task.stage || 'preparation') === filterStage) && (filterStatus === 'all' || task.status === filterStatus) && (!taskParams.get('occurrenceId') || task.eventOccurrenceId === taskParams.get('occurrenceId')))
    .sort((a, b) => taskSort === 'title' ? localize(a.title, language).localeCompare(localize(b.title, language), language) : (a.dueUtc || '9999').localeCompare(b.dueUtc || '9999'))
  const pages = Math.max(1, Math.ceil(taskRows.length / 10)), page = Math.min(taskPage, pages)
  const groupedTasks = groupEventTasks(taskRows.slice((page - 1) * 10, page * 10))
  const eligibleCandidates = candidates.filter(candidate => candidate.id === currentMemberId || data?.members.some(member => member.memberId === candidate.id && member.status === 'accepted') || data?.roles.some(role => role.memberId === candidate.id && role.status === 'accepted'))


  return (
    <div className="space-y-4">
      <EventActivityPlanPanel eventId={eventId} groupId={groupId} zh={language === 'zh'} eventContext={eventContext} onSaved={onSaved} onPlanChange={setActivityPlan} onBusy={setAiBusy}/>
      {data ? <EventTeamModules eventId={eventId} zh={language === 'zh'} moduleSelections={moduleSelections} state={{ data, candidates, error, loading: state === 'loading', reload: load }} onBusy={setBusy} onSaved={async () => { await load(); await onSaved?.() }} /> : null}
      <AppSectionCard summary={surfaceStatusSummary(state, language) ?? (language === 'zh' ? eventOperationsSurfacesText.collaborators.zh(data?.members.length || 0) : eventOperationsSurfacesText.collaborators.en(data?.members.length || 0))} title={language === 'zh' ? eventOperationsSurfacesText.collaboratorsLabel.zh : eventOperationsSurfacesText.collaboratorsLabel.en} subtitle={language === 'zh' ? eventOperationsSurfacesText.inviteMembersToHelpPrepareEachMemberAcceptsOr.zh : eventOperationsSurfacesText.inviteMembersToHelpPrepareEachMemberAcceptsOr.en} action={<AppBadge variant={item.readiness === 'ready' ? 'success' : 'warning'}>{item.readiness}</AppBadge>}>
        <SurfaceState state={state} language={language} error={error} onRetry={() => void load()} />
        {data ? <div className="space-y-6">
          {data.readinessBlockers.length ? <ul className="space-y-2" aria-label={language === 'zh' ? eventOperationsSurfacesText.readinessBlockers.zh : eventOperationsSurfacesText.readinessBlockers.en}>{data.readinessBlockers.map((blocker, index) => <li key={`${blocker.en}-${index}`} className="rounded-xl border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-950">{localize(blocker, language)}</li>)}</ul> : null}
          <section aria-labelledby="event-team-heading">
            <div className="flex flex-wrap items-center justify-between gap-3"><h3 id="event-team-heading" className="font-black text-[#18332d]">{setupFlow ? (language === 'zh' ? eventOperationsSurfacesText.teamMembers.zh : eventOperationsSurfacesText.teamMembers.en) : (language === 'zh' ? eventOperationsSurfacesText.teamRoles.zh : eventOperationsSurfacesText.teamRoles.en)}</h3></div>
            <div className="mt-3 grid gap-3 tablet:grid-cols-2 desktop:grid-cols-3">
              {data.members.map((member) => <article key={member.id} className="rounded-2xl border border-[#2f4b42]/10 bg-[#fbfcf8] p-4"><p className="font-bold text-[#18332d]">{member.displayName || member.memberId}</p><AppBadge variant={member.status === 'accepted' ? 'success' : member.status === 'declined' ? 'danger' : 'warning'}>{roleStatusLabel(member.status, language === 'zh')}</AppBadge>{member.memberId === currentMemberId && member.status === 'invited' ? <div className="mt-3 flex gap-2"><AppActionButton size="sm" variant="primary" disabled={busy} onClick={() => void mutate(() => eventOperationsService.respondToTeamInvite(eventId, member.id, true))}>{language === 'zh' ? eventOperationsSurfacesText.accept.zh : eventOperationsSurfacesText.accept.en}</AppActionButton><AppActionButton size="sm" disabled={busy} onClick={() => void mutate(() => eventOperationsService.respondToTeamInvite(eventId, member.id, false))}>{language === 'zh' ? eventOperationsSurfacesText.decline.zh : eventOperationsSurfacesText.decline.en}</AppActionButton></div> : null}</article>)}
              {!setupFlow && data.roles.map((role) => <article key={role.id} className="rounded-2xl border border-[#2f4b42]/10 bg-white p-4"><p className="text-xs font-bold text-[#66766f]">{role.roleRequirementKey}</p><p className="mt-1 text-sm text-[#40554e]">{candidates.find((member) => member.id === role.memberId)?.displayName || role.memberId}</p><AppBadge variant={role.status === 'accepted' ? 'success' : role.status === 'declined' ? 'danger' : 'warning'}>{role.status}</AppBadge>{role.memberId === currentMemberId && role.status === 'invited' ? <div className="mt-3 flex gap-2"><AppActionButton size="sm" variant="primary" disabled={busy} onClick={() => void mutate(() => eventOperationsService.respondToRoleInvitation(eventId, role.id, true))}>{language === 'zh' ? eventOperationsSurfacesText.acceptRole.zh : eventOperationsSurfacesText.acceptRole.en}</AppActionButton><AppActionButton size="sm" disabled={busy} onClick={() => void mutate(() => eventOperationsService.respondToRoleInvitation(eventId, role.id, false))}>{language === 'zh' ? eventOperationsSurfacesText.decline.zh : eventOperationsSurfacesText.decline.en}</AppActionButton></div> : null}</article>)}
            </div>
            {data.canManage ? <form className="mt-4 flex flex-col gap-2 tablet:flex-row" onSubmit={(event) => { event.preventDefault(); if (inviteeId) void mutate(() => eventOperationsService.inviteTeamMember(eventId, inviteeId).then(value => { setInviteeId(''); return value })) }}><label className="sr-only" htmlFor="event-team-invitee">{language === 'zh' ? eventOperationsSurfacesText.inviteMember.zh : eventOperationsSurfacesText.inviteMember.en}</label><select id="event-team-invitee" value={inviteeId} onChange={(event) => setInviteeId(event.target.value)} className={fieldClass}><option value="">{language === 'zh' ? eventOperationsSurfacesText.selectGroupMember.zh : eventOperationsSurfacesText.selectGroupMember.en}</option>{candidates.filter((candidate) => !data.members.some((member) => member.memberId === candidate.id && !member.endedUtc && ['invited', 'accepted'].includes(member.status))).map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.displayName || candidate.id}</option>)}</select><AppActionButton type="submit" variant="primary" disabled={busy || !inviteeId}>{language === 'zh' ? eventOperationsSurfacesText.sendInvitation.zh : eventOperationsSurfacesText.sendInvitation.en}</AppActionButton></form> : null}
          </section>
        </div> : null}
      </AppSectionCard>

      {data ? <AppSectionCard summary={surfaceStatusSummary(state, language) ?? (language === 'zh' ? eventOperationsSurfacesText.tasksDone.zh(data.tasks.length, data.tasks.filter(task => task.status === 'done').length) : eventOperationsSurfacesText.tasksDone.en(data.tasks.length, data.tasks.filter(task => task.status === 'done').length))} title={language === 'zh' ? eventOperationsSurfacesText.customTasksAndPreparation.zh : eventOperationsSurfacesText.customTasksAndPreparation.en} subtitle={language === 'zh' ? eventOperationsSurfacesText.delegateWorkBeyondTheEnabledModulesAssigneesAcceptAnd.zh : eventOperationsSurfacesText.delegateWorkBeyondTheEnabledModulesAssigneesAcceptAnd.en}>
        {data.canManage ? <DetailsWorkspace zh={language === 'zh'} active readOnly={busy || !canManage}
          labels={{ workspace: language === 'zh' ? eventOperationsSurfacesText.tasksAndHandoffsWorkspace.zh : eventOperationsSurfacesText.tasksAndHandoffsWorkspace.en, form: language === 'zh' ? eventOperationsSurfacesText.taskForm.zh : eventOperationsSurfacesText.taskForm.en, assistant: language === 'zh' ? eventOperationsSurfacesText.aiTaskAssistant.zh : eventOperationsSurfacesText.aiTaskAssistant.en }}
          assistant={active => <EventFormAssistant key={`${currentMemberId}:${eventId}`} eventId={eventId} scope="tasks" zh={language === 'zh'} active={active} onBusy={setAiBusy}
            form={{ title: { en: taskTitleEn, zh: taskTitleZh }, dueLocal: taskDue, stage: taskStage, requiresApproval, isRestricted }}
            contextSignature={JSON.stringify([assigneeId, reviewerId, taskOccurrence, taskActivity, taskDescription])}
            onAdopt={(form, fields) => {
              if (fields.includes('title')) { const title = form.title as Bilingual; setTaskTitleEn(title.en); setTaskTitleZh(title.zh) }
              if (fields.includes('dueLocal')) setTaskDue(form.dueLocal as string)
              if (fields.includes('stage')) setTaskStage(form.stage as string)
              if (fields.includes('requiresApproval')) setRequiresApproval(form.requiresApproval as boolean)
              if (fields.includes('isRestricted')) setIsRestricted(form.isRestricted as boolean)
            }} />}
          form={<form className="mb-5" onSubmit={createTask}><fieldset disabled={busy || !canManage} className="grid gap-3 tablet:grid-cols-2">
            <label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.linkedActivityOptional.zh : eventOperationsSurfacesText.linkedActivityOptional.en}<select className={fieldClass} value={taskActivity} onChange={e => setTaskActivity(e.target.value)}><option value="">—</option>{activityPlan?.activities.map(activity => <option key={activity.id} value={activity.id}>{localize(activity.name, language)}</option>)}</select></label>
            <div data-detail-field="title" className="min-w-0 tablet:col-span-2"><BilingualField primaryLanguage={language} label={language === 'zh' ? eventOperationsSurfacesText.taskTitle.zh : eventOperationsSurfacesText.taskTitle.en} required maxLength={300} value={{ en: taskTitleEn, zh: taskTitleZh }} onChange={value => { setTaskTitleEn(value.en); setTaskTitleZh(value.zh) }} /></div>
            <div className="min-w-0 tablet:col-span-2"><BilingualField primaryLanguage={language} label={language === 'zh' ? eventOperationsSurfacesText.taskDescription.zh : eventOperationsSurfacesText.taskDescription.en} multiline maxLength={2000} value={taskDescription} onChange={setTaskDescription} /></div>
            <label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.assignee.zh : eventOperationsSurfacesText.assignee.en}<select required className={fieldClass} value={assigneeId} onChange={e => setAssigneeId(e.target.value)}><option value="">{language === 'zh' ? eventOperationsSurfacesText.unassigned.zh : eventOperationsSurfacesText.unassigned.en}</option>{eligibleCandidates.map(member => <option key={member.id} value={member.id}>{member.displayName || member.id}</option>)}</select></label>
            <label data-detail-field="dueLocal" className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.due.zh : eventOperationsSurfacesText.due.en}<input type="datetime-local" className={fieldClass} value={taskDue} onChange={e => setTaskDue(e.target.value)} /></label>
            <label data-detail-field="stage" className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.stage.zh : eventOperationsSurfacesText.stage.en}<select className={fieldClass} value={taskStage} onChange={e => setTaskStage(e.target.value)}>{workStages.map(stage => <option key={stage} value={stage}>{workStageText(stage, language === 'zh')}</option>)}</select></label>
            <label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.occurrence.zh : eventOperationsSurfacesText.occurrence.en}<select className={fieldClass} value={taskOccurrence} onChange={e => setTaskOccurrence(e.target.value)}><option value="">{language === 'zh' ? eventOperationsSurfacesText.wholeEvent.zh : eventOperationsSurfacesText.wholeEvent.en}</option>{taskOccurrences.map(occurrence => <option key={occurrence.id} value={occurrence.id}>{new Date(occurrence.startUtc).toLocaleString(language)}</option>)}</select></label>
            <label data-detail-field="requiresApproval" className="flex min-h-11 items-center gap-2 text-sm font-bold text-[#40554e]"><input type="checkbox" checked={requiresApproval} onChange={e => setRequiresApproval(e.target.checked)} />{language === 'zh' ? eventOperationsSurfacesText.requiresApproval.zh : eventOperationsSurfacesText.requiresApproval.en}</label>
            {requiresApproval ? <label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.assignedReviewer.zh : eventOperationsSurfacesText.assignedReviewer.en}<select className={fieldClass} value={reviewerId} onChange={e => setReviewerId(e.target.value)}><option value="">{language === 'zh' ? eventOperationsSurfacesText.defaultOwnerNoSelfReview.zh : eventOperationsSurfacesText.defaultOwnerNoSelfReview.en}</option>{candidates.filter(candidate => candidate.id !== assigneeId && (candidate.id === currentMemberId || data.members.some(member => member.memberId === candidate.id && member.status === 'accepted') || data.roles.some(role => role.memberId === candidate.id && role.status === 'accepted'))).map(candidate => <option key={candidate.id} value={candidate.id}>{candidate.displayName || candidate.id}</option>)}</select></label> : null}
            <label data-detail-field="isRestricted" className="flex min-h-11 items-center gap-2 text-sm font-bold text-[#40554e]"><input type="checkbox" checked={isRestricted} onChange={e => setIsRestricted(e.target.checked)} />{language === 'zh' ? eventOperationsSurfacesText.restrictedTask.zh : eventOperationsSurfacesText.restrictedTask.en}</label>
            <AppActionButton className="self-end" type="submit" variant="primary" disabled={busy || aiBusy || !canManage}>{language === 'zh' ? eventOperationsSurfacesText.addTask.zh : eventOperationsSurfacesText.addTask.en}</AppActionButton>
          </fieldset></form>} /> : null}
        <label className="mb-3 grid gap-2 text-sm">{language === 'zh' ? eventOperationsSurfacesText.tasksByStage.zh : eventOperationsSurfacesText.tasksByStage.en}<select className={fieldClass} value={filterStage} onChange={e => { setFilterStage(e.target.value); setTaskPage(1) }}><option value="all">{language === 'zh' ? eventOperationsSurfacesText.allStages.zh : eventOperationsSurfacesText.allStages.en}</option>{workStages.map(stage => <option key={stage} value={stage}>{workStageText(stage, language === 'zh')}</option>)}</select></label><div className="mb-3 grid gap-3 tablet:grid-cols-2"><label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.taskStatus.zh : eventOperationsSurfacesText.taskStatus.en}<select className={fieldClass} value={filterStatus} onChange={e => { setFilterStatus(e.target.value); setTaskPage(1) }}><option value="all">{language === 'zh' ? eventOperationsSurfacesText.allStatuses.zh : eventOperationsSurfacesText.allStatuses.en}</option>{taskColumns.map(column => <option key={column.status} value={column.status}>{column[language]}</option>)}</select></label><label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.sort.zh : eventOperationsSurfacesText.sort.en}<select className={fieldClass} value={taskSort} onChange={e => { setTaskSort(e.target.value); setTaskPage(1) }}><option value="due">{language === 'zh' ? eventOperationsSurfacesText.dueDate.zh : eventOperationsSurfacesText.dueDate.en}</option><option value="title">{language === 'zh' ? eventOperationsSurfacesText.title.zh : eventOperationsSurfacesText.title.en}</option></select></label></div>{taskRows.length ? <div className="grid gap-3 desktop:grid-cols-2">{taskColumns.filter(column => groupedTasks[column.status].length).map((column) => <section key={column.status} className="rounded-2xl bg-[#eef4ef] p-3"><h3 className="mb-3 text-sm font-black text-[#18332d]">{language === 'zh' ? column.zh : column.en} <span className="text-[#66766f]">{groupedTasks[column.status].length}</span></h3><div className="space-y-3">{groupedTasks[column.status].map((task) => <TaskCard eventId={eventId} key={task.id} task={task} tasks={data.tasks} canManage={data.canManage} language={language} busy={busy} onStatus={(status) => void mutate(() => eventOperationsService.updateTask(eventId, task, status))} onDependency={(dependsOnTaskId) => void mutate(() => eventOperationsService.addTaskDependency(eventId, task.id, dependsOnTaskId))} onBlock={(reason) => void mutate(() => eventOperationsService.addTaskBlocker(eventId, task.id, reason))} onResolve={(blockerId, resolution) => void mutate(() => eventOperationsService.resolveTaskBlocker(eventId, task.id, blockerId, resolution))} />)}</div></section>)}</div> : <AppEmptyState title={language === 'zh' ? eventOperationsSurfacesText.noTasksYet.zh : eventOperationsSurfacesText.noTasksYet.en} description={language === 'zh' ? eventOperationsSurfacesText.requiredTasksFeedBlockersAndOverdueStatusIntoReadiness.zh : eventOperationsSurfacesText.requiredTasksFeedBlockersAndOverdueStatusIntoReadiness.en} />}
        <div className="mt-4 flex flex-wrap items-center gap-3"><AppActionButton disabled={page === 1} onClick={() => setTaskPage(page - 1)}>{language === 'zh' ? eventOperationsSurfacesText.previous.zh : eventOperationsSurfacesText.previous.en}</AppActionButton><span className="text-sm">{page} / {pages}</span><AppActionButton disabled={page === pages} onClick={() => setTaskPage(page + 1)}>{language === 'zh' ? eventOperationsSurfacesText.next.zh : eventOperationsSurfacesText.next.en}</AppActionButton></div>
      </AppSectionCard> : null}
    </div>
  )
}

const TaskCard = ({ eventId, task, tasks, canManage, language, busy, onStatus, onDependency, onBlock, onResolve }: { eventId: string; task: EventTask; tasks: EventTask[]; canManage: boolean; language: 'en' | 'zh'; busy: boolean; onStatus: (status: EventTaskStatus) => void; onDependency: (dependsOnTaskId: string) => void; onBlock: (reason: string) => void; onResolve: (blockerId: string, resolution: string) => void }) => {
  const currentMemberId = useAuthStore().me?.id
  const [reason, setReason] = useState('')
  const [resolutions, setResolutions] = useState<Record<string, string>>({})
  const [dependencyId, setDependencyId] = useState('')
  const existingDependencies = new Set(task.dependencies.map((dependency) => dependency.dependsOnEventTaskId))
  const dependencyCandidates = tasks.filter((candidate) => candidate.id !== task.id && !existingDependencies.has(candidate.id) && candidate.status !== 'cancelled')
  const availableStatuses = (canManage ? ['todo', 'inProgress', 'blocked', 'done', 'cancelled'] : ['todo', 'inProgress', 'blocked', 'done']).filter(status => status !== 'done' || !task.requiresApproval || task.status === 'done') as EventTaskStatus[]
  return <article className="rounded-xl border border-[#2f4b42]/10 bg-white p-3 shadow-sm"><div className="flex items-start justify-between gap-2"><Link className="font-bold text-[#176b5a] underline underline-offset-4" to={`/events/${eventId}/tasks/${task.id}`}>{localize(task.title, language)}</Link>{task.isRequired ? <AppBadge variant="warning">{language === 'zh' ? eventOperationsSurfacesText.required.zh : eventOperationsSurfacesText.required.en}</AppBadge> : null}</div>{task.assignmentStatus ? <p className="mt-2 text-sm">{roleStatusLabel(task.assignmentStatus, language === 'zh')}</p> : null}{task.preparationUpdatedUtc ? <p className="mt-1 text-xs text-[#66766f]">{language === 'zh' ? eventOperationsSurfacesText.preparationRecorded.zh : eventOperationsSurfacesText.preparationRecorded.en}</p> : null}{task.dueUtc ? <time className="mt-2 block text-xs text-[#66766f]">{new Date(task.dueUtc).toLocaleString()}</time> : null}{task.requiresApproval ? <p className="mt-1 text-xs font-bold text-amber-800">{language === 'zh' ? eventOperationsSurfacesText.approvalRequired.zh : eventOperationsSurfacesText.approvalRequired.en}</p> : null}<select className={`${fieldClass} mt-3`} value={task.status} aria-label={language === 'zh' ? eventOperationsSurfacesText.taskProgress.zh : eventOperationsSurfacesText.taskProgress.en} disabled={busy || (!canManage && task.assignedMemberId !== currentMemberId) || (task.assignmentStatus !== undefined && task.assignmentStatus !== 'accepted') || Boolean(task.sourceType) || task.approvalStatus === 'pendingReview'} onChange={(event) => onStatus(event.target.value as EventTaskStatus)}>{availableStatuses.map((status) => <option key={status} value={status}>{({ todo: language === 'zh' ? eventOperationsSurfacesText.toDo.zh : eventOperationsSurfacesText.toDo.en, inProgress: language === 'zh' ? eventOperationsSurfacesText.inProgressLabel.zh : eventOperationsSurfacesText.inProgressLabel.en, blocked: language === 'zh' ? eventOperationsSurfacesText.blockedLabel.zh : eventOperationsSurfacesText.blockedLabel.en, done: language === 'zh' ? eventOperationsSurfacesText.doneLabel.zh : eventOperationsSurfacesText.doneLabel.en, cancelled: language === 'zh' ? eventOperationsSurfacesText.cancelledLabel.zh : eventOperationsSurfacesText.cancelledLabel.en })[status]}</option>)}</select>{task.dependencies.length ? <ul className="mt-2 space-y-1 text-xs text-[#66766f]">{task.dependencies.map((dependency) => <li key={dependency.id}>{language === 'zh' ? eventOperationsSurfacesText.dependsOn.zh : eventOperationsSurfacesText.dependsOn.en}{localize(tasks.find((candidate) => candidate.id === dependency.dependsOnEventTaskId)?.title ?? { en: dependency.dependsOnEventTaskId, zh: dependency.dependsOnEventTaskId }, language)}</li>)}</ul> : null}{canManage && dependencyCandidates.length ? <div className="mt-2 flex gap-2"><select aria-label={language === 'zh' ? eventOperationsSurfacesText.dependencyTask.zh : eventOperationsSurfacesText.dependencyTask.en} className={fieldClass} value={dependencyId} onChange={(event) => setDependencyId(event.target.value)}><option value="">{language === 'zh' ? eventOperationsSurfacesText.addDependency.zh : eventOperationsSurfacesText.addDependency.en}</option>{dependencyCandidates.map((candidate) => <option key={candidate.id} value={candidate.id}>{localize(candidate.title, language)}</option>)}</select><AppActionButton size="sm" disabled={busy || !dependencyId} onClick={() => { onDependency(dependencyId); setDependencyId('') }}>{language === 'zh' ? eventOperationsSurfacesText.add.zh : eventOperationsSurfacesText.add.en}</AppActionButton></div> : null}{task.blockers.filter((blocker) => !blocker.resolvedUtc).map((blocker) => { const resolution = resolutions[blocker.id] ?? ''; return <div key={blocker.id} className="mt-2 rounded-lg border border-amber-200 bg-amber-50 p-2"><p className="text-xs text-amber-950">{blocker.reason}</p><div className="mt-2 flex gap-2"><input className={fieldClass} value={resolution} onChange={(event) => setResolutions((current) => ({ ...current, [blocker.id]: event.target.value }))} placeholder={language === 'zh' ? eventOperationsSurfacesText.resolution.zh : eventOperationsSurfacesText.resolution.en} /><AppActionButton size="sm" disabled={busy || !resolution.trim()} onClick={() => { onResolve(blocker.id, resolution.trim()); setResolutions((current) => ({ ...current, [blocker.id]: '' })) }}>{language === 'zh' ? eventOperationsSurfacesText.resolve.zh : eventOperationsSurfacesText.resolve.en}</AppActionButton></div></div> })}{task.status !== 'done' ? <div className="mt-2 flex gap-2"><input className={fieldClass} value={reason} onChange={(event) => setReason(event.target.value)} placeholder={language === 'zh' ? eventOperationsSurfacesText.blockerReason.zh : eventOperationsSurfacesText.blockerReason.en} /><AppActionButton size="sm" disabled={busy || !reason.trim()} onClick={() => { onBlock(reason.trim()); setReason('') }}>{language === 'zh' ? eventOperationsSurfacesText.block.zh : eventOperationsSurfacesText.block.en}</AppActionButton></div> : null}</article>
}

const OccurrencePicker = ({ eventId, language, value, onChange }: { eventId: string; language: 'en' | 'zh'; value: string; onChange: (id: string, occurrence?: EventOccurrence) => void }) => {
  const [occurrences, setOccurrences] = useState<EventOccurrence[]>([])
  useEffect(() => {
    void eventOperationsService.listOccurrences(eventId).then((values) => {
      setOccurrences(values)
      const selected = values.find((occurrence) => occurrence.id === value) ?? values[0]
      if (selected) onChange(selected.id, selected)
    })
  }, [eventId, onChange])
  const selectOccurrence = (id: string) => onChange(id, occurrences.find((occurrence) => occurrence.id === id))
  return <label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.occurrenceLocalTime.zh : eventOperationsSurfacesText.occurrenceLocalTime.en}<select className={fieldClass} value={value} onChange={(event) => selectOccurrence(event.target.value)}><option value="">{language === 'zh' ? eventOperationsSurfacesText.selectOccurrence.zh : eventOperationsSurfacesText.selectOccurrence.en}</option>{occurrences.map((occurrence) => <option key={occurrence.id} value={occurrence.id}>{formatLocalOccurrenceTime(occurrence.startUtc, language)}</option>)}</select></label>
}

export const EventProgrammePanel = ({ eventId, language, item, onBusyChange, onSaved }: EventSurfaceProps) => {
  const [printData, setPrintData] = useState<EventProgramme | null>(null)
  const [occurrenceId, setOccurrenceId] = useState('')
  const [data, setData] = useState<EventProgramme | null>(null)
  const [state, setState] = useState<AsyncState>('loading')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [titleEn, setTitleEn] = useState('')
  const [titleZh, setTitleZh] = useState('')
  const [start, setStart] = useState('')
  const [end, setEnd] = useState('')
  useArrangementDraft(Boolean(titleEn || titleZh))
  const stableSetOccurrence = useCallback((id: string) => setOccurrenceId(id), [])
  const load = useCallback(async () => { if (!occurrenceId) return; setState('loading'); try { const next = await eventOperationsService.getProgramme(eventId, occurrenceId); setData(next); setState(next.sessions.length ? 'ready' : 'empty') } catch (reason) { setState(resolveState(reason)); setError(normalizeApiError(reason).message) } }, [eventId, occurrenceId])
  useEffect(() => { void load() }, [load])
  useEffect(() => { onBusyChange?.(busy) }, [busy, onBusyChange])
  const create = async (event: FormEvent) => { event.preventDefault(); if (!data) return; setBusy(true); try { const next = await eventOperationsService.createSession(eventId, occurrenceId, data.eTag, { title: { en: titleEn, zh: titleZh }, startUtc: fromLocalInput(start), endUtc: fromLocalInput(end), placeJson: '{}', status: 'draft' }); setData(next); setState('ready'); setTitleEn(''); setTitleZh(''); await onSaved?.() } catch (reason) { setState(resolveState(reason)); setError(normalizeApiError(reason).message) } finally { setBusy(false) } }
  return <div className="space-y-4 print:space-y-2">{printData ? <EventProgrammePrintView programme={printData} zh={language === 'zh'} onClose={() => setPrintData(null)} /> : null}<AppSectionCard summary={surfaceStatusSummary(state, language) ?? (occurrenceId ? (language === 'zh' ? eventOperationsSurfacesText.programmeSessions.zh(data?.sessions.length || 0) : eventOperationsSurfacesText.programmeSessions.en(data?.sessions.length || 0)) : (language === 'zh' ? eventOperationsSurfacesText.selectAnOccurrence.zh : eventOperationsSurfacesText.selectAnOccurrence.en))} title={localize(item.label, language)} subtitle={language === 'zh' ? eventOperationsSurfacesText.selectAnOccurrenceFirstMaterializedOccurrencesAreNotOverwritten.zh : eventOperationsSurfacesText.selectAnOccurrenceFirstMaterializedOccurrencesAreNotOverwritten.en} action={<div className="flex gap-2"><AppBadge variant={item.readiness === 'ready' ? 'success' : 'warning'}>{item.readiness}</AppBadge><AppActionButton size="sm" disabled={!data || busy} onClick={() => { if (data) setPrintData(data) }}>{language === 'zh' ? eventOperationsSurfacesText.printRunSheet.zh : eventOperationsSurfacesText.printRunSheet.en}</AppActionButton></div>}><OccurrencePicker eventId={eventId} language={language} value={occurrenceId} onChange={stableSetOccurrence} />{occurrenceId ? <div className="mt-4"><SurfaceState state={state} language={language} error={error} onRetry={() => void load()} /></div> : null}</AppSectionCard>{data?.canManage ? <AppSectionCard summary={language === 'zh' ? `${titleZh || titleEn || eventOperationsSurfacesText.eventProgrammePanel} · ${start || eventOperationsSurfacesText.eventProgrammePanel2}` : `${titleEn || titleZh || 'Untitled'} · ${start || 'Start time needed'}`} title={language === 'zh' ? eventOperationsSurfacesText.addSession.zh : eventOperationsSurfacesText.addSession.en}><form className="grid gap-3 tablet:grid-cols-2 desktop:grid-cols-5" onSubmit={(event) => void create(event)}><label className={labelClass}>English<input className={fieldClass} value={titleEn} onChange={(event) => setTitleEn(event.target.value)} required /></label><label className={labelClass}>{eventOperationsSurfacesText.label}<input className={fieldClass} value={titleZh} onChange={(event) => setTitleZh(event.target.value)} required /></label><label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.start.zh : eventOperationsSurfacesText.start.en}<input type="datetime-local" className={fieldClass} value={start} onChange={(event) => setStart(event.target.value)} required /></label><label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.end.zh : eventOperationsSurfacesText.end.en}<input type="datetime-local" className={fieldClass} value={end} onChange={(event) => setEnd(event.target.value)} required /></label><AppActionButton className="self-end" type="submit" variant="primary" disabled={busy}>{language === 'zh' ? eventOperationsSurfacesText.addLabel.zh : eventOperationsSurfacesText.addLabel.en}</AppActionButton></form></AppSectionCard> : null}{data?.sessions.length ? <AppSectionCard title={language === 'zh' ? eventOperationsSurfacesText.programmeSessionsLabel.zh : eventOperationsSurfacesText.programmeSessionsLabel.en} summary={language === 'zh' ? eventOperationsSurfacesText.sessionsItems.zh(data.sessions.length, data.sessions.reduce((count, session) => count + session.items.length, 0)) : eventOperationsSurfacesText.sessionsItems.en(data.sessions.length, data.sessions.reduce((count, session) => count + session.items.length, 0))}>{data.sessions.map((session) => <SessionCard key={session.id} data={data} session={session} language={language} busy={busy} onBusy={setBusy} onData={async value => { setData(value); await onSaved?.() }} onFailure={(reason) => { setState(resolveState(reason)); setError(normalizeApiError(reason).message) }} />)}</AppSectionCard> : null}{data && !data.sessions.length ? <AppEmptyState title={language === 'zh' ? eventOperationsSurfacesText.noSessionsYet.zh : eventOperationsSurfacesText.noSessionsYet.en} description={language === 'zh' ? eventOperationsSurfacesText.createTheFirstSessionToBeginTheRunSheet.zh : eventOperationsSurfacesText.createTheFirstSessionToBeginTheRunSheet.en} /> : null}</div>
}

const SessionCard = ({ data, session, language, busy, onBusy, onData, onFailure }: { data: EventProgramme; session: EventProgramme['sessions'][number]; language: 'en' | 'zh'; busy: boolean; onBusy: (value: boolean) => void; onData: (value: EventProgramme) => void | Promise<void>; onFailure: (error: unknown) => void }) => {
  const [titleEn, setTitleEn] = useState(''); const [titleZh, setTitleZh] = useState(''); const [duration, setDuration] = useState(10)
  const [sessionTitleEn, setSessionTitleEn] = useState(session.title.en); const [sessionTitleZh, setSessionTitleZh] = useState(session.title.zh); const [sessionStatus, setSessionStatus] = useState(session.status)
  const { requestConfirmation, confirmationModal } = useConfirmation()
  useArrangementDraft(Boolean(titleEn || titleZh || sessionTitleEn !== session.title.en || sessionTitleZh !== session.title.zh || sessionStatus !== session.status))
  const addItem = async (event: FormEvent) => { event.preventDefault(); onBusy(true); try { await onData(await eventOperationsService.createProgramItem(data.eventId, data.occurrenceId, session.id, data.eTag, { title: { en: titleEn, zh: titleZh }, description: { en: '', zh: '' }, startOffsetMinutes: session.items.reduce((total, item) => Math.max(total, item.startOffsetMinutes + item.durationMinutes), 0), durationMinutes: duration })); setTitleEn(''); setTitleZh('') } catch (reason) { onFailure(reason) } finally { onBusy(false) } }
  const move = async (index: number, delta: number) => { const target = index + delta; if (target < 0 || target >= session.items.length) return; const ids = session.items.map((item) => item.id); [ids[index], ids[target]] = [ids[target], ids[index]]; onBusy(true); try { await onData(await eventOperationsService.reorderProgramItems(data.eventId, data.occurrenceId, session.id, data.eTag, ids)) } catch (reason) { onFailure(reason) } finally { onBusy(false) } }
  const saveSession = async (event: FormEvent) => { event.preventDefault(); onBusy(true); try { await onData(await eventOperationsService.updateSession(data.eventId, data.occurrenceId, session.id, data.eTag, { title: { en: sessionTitleEn, zh: sessionTitleZh }, startUtc: session.startUtc, endUtc: session.endUtc, placeJson: session.placeJson, leadMemberId: session.leadMemberId, status: sessionStatus })) } catch (reason) { onFailure(reason) } finally { onBusy(false) } }
  const deleteSession = async () => { if (!await requestConfirmation({ title: language === 'zh' ? eventOperationsSurfacesText.deleteSession.zh : eventOperationsSurfacesText.deleteSession.en, description: language === 'zh' ? eventOperationsSurfacesText.onlySessionsWithoutLinkedServiceSlotsCanBeDeleted.zh : eventOperationsSurfacesText.onlySessionsWithoutLinkedServiceSlotsCanBeDeleted.en, tone: 'danger' })) return; onBusy(true); try { await onData(await eventOperationsService.deleteSession(data.eventId, data.occurrenceId, session.id, data.eTag)) } catch (reason) { onFailure(reason) } finally { onBusy(false) } }
  return <><NativeSectionCard title={localize(session.title, language)} subtitle={`${new Date(session.startUtc).toLocaleString()} – ${new Date(session.endUtc).toLocaleTimeString()} · ${session.status}`}>{data.canManage ? <form className="mb-4 grid gap-2 tablet:grid-cols-[1fr_1fr_9rem_auto_auto] print:hidden" onSubmit={(event) => void saveSession(event)}><input aria-label="Session English title" className={fieldClass} value={sessionTitleEn} onChange={(event) => setSessionTitleEn(event.target.value)} required /><input aria-label="Session Chinese title" className={fieldClass} value={sessionTitleZh} onChange={(event) => setSessionTitleZh(event.target.value)} required /><select aria-label="Session status" className={fieldClass} value={sessionStatus} onChange={(event) => setSessionStatus(event.target.value as typeof sessionStatus)}><option value="draft">draft</option><option value="confirmed">confirmed</option><option value="cancelled">cancelled</option></select><AppActionButton type="submit" disabled={busy}>{language === 'zh' ? eventOperationsSurfacesText.save.zh : eventOperationsSurfacesText.save.en}</AppActionButton><AppActionButton variant="danger" disabled={busy} onClick={() => void deleteSession()}>{language === 'zh' ? eventOperationsSurfacesText.delete.zh : eventOperationsSurfacesText.delete.en}</AppActionButton></form> : null}<ol className="divide-y divide-[#2f4b42]/10">{session.items.map((item, index) => <ProgrammeItemRow key={item.id} data={data} item={item} index={index} itemCount={session.items.length} language={language} busy={busy} onMove={(delta) => void move(index, delta)} onBusy={onBusy} onData={onData} onFailure={onFailure} />)}</ol>{data.canManage ? <form className="mt-4 grid gap-3 tablet:grid-cols-[1fr_1fr_7rem_auto] print:hidden" onSubmit={(event) => void addItem(event)}><input aria-label="English title" className={fieldClass} value={titleEn} onChange={(event) => setTitleEn(event.target.value)} placeholder="English title" required /><input aria-label={eventOperationsSurfacesText.sessionCard} className={fieldClass} value={titleZh} onChange={(event) => setTitleZh(event.target.value)} placeholder={eventOperationsSurfacesText.sessionCard2} required /><input aria-label="Duration" type="number" min="1" className={fieldClass} value={duration} onChange={(event) => setDuration(Number(event.target.value))} /><AppActionButton type="submit" variant="primary" disabled={busy}>{language === 'zh' ? eventOperationsSurfacesText.addItem.zh : eventOperationsSurfacesText.addItem.en}</AppActionButton></form> : null}</NativeSectionCard>{confirmationModal}</>
}

const ProgrammeItemRow = ({ data, item, index, itemCount, language, busy, onMove, onBusy, onData, onFailure }: { data: EventProgramme; item: EventProgramme['sessions'][number]['items'][number]; index: number; itemCount: number; language: 'en' | 'zh'; busy: boolean; onMove: (delta: number) => void; onBusy: (value: boolean) => void; onData: (value: EventProgramme) => void | Promise<void>; onFailure: (error: unknown) => void }) => {
  const [editing, setEditing] = useState(false); const [titleEn, setTitleEn] = useState(item.title.en); const [titleZh, setTitleZh] = useState(item.title.zh); const [duration, setDuration] = useState(item.durationMinutes)
  const { requestConfirmation, confirmationModal } = useConfirmation()
  const save = async () => { onBusy(true); try { await onData(await eventOperationsService.updateProgramItem(data.eventId, data.occurrenceId, item.id, data.eTag, { title: { en: titleEn, zh: titleZh }, description: item.description, startOffsetMinutes: item.startOffsetMinutes, durationMinutes: duration, ownerMemberId: item.ownerMemberId })); setEditing(false) } catch (reason) { onFailure(reason) } finally { onBusy(false) } }
  const remove = async () => { if (!await requestConfirmation({ title: language === 'zh' ? eventOperationsSurfacesText.deleteProgrammeItem.zh : eventOperationsSurfacesText.deleteProgrammeItem.en, description: language === 'zh' ? eventOperationsSurfacesText.linkedServiceSlotsMustBeRemovedFirst.zh : eventOperationsSurfacesText.linkedServiceSlotsMustBeRemovedFirst.en, tone: 'danger' })) return; onBusy(true); try { await onData(await eventOperationsService.deleteProgramItem(data.eventId, data.occurrenceId, item.id, data.eTag)) } catch (reason) { onFailure(reason) } finally { onBusy(false) } }
  return <><li className="grid gap-2 py-3 tablet:grid-cols-[5rem_1fr_auto]"><span className="font-mono text-sm text-[#66766f]">+{item.startOffsetMinutes}m</span>{editing ? <div className="grid gap-2 tablet:grid-cols-3"><input className={fieldClass} value={titleEn} onChange={(event) => setTitleEn(event.target.value)} /><input className={fieldClass} value={titleZh} onChange={(event) => setTitleZh(event.target.value)} /><input className={fieldClass} type="number" min="1" value={duration} onChange={(event) => setDuration(Number(event.target.value))} /></div> : <div><p className="font-bold text-[#18332d]">{localize(item.title, language)}</p><p className="text-xs text-[#66766f]">{item.durationMinutes} min</p></div>}{data.canManage ? <div className="flex flex-wrap gap-1 print:hidden"><AppActionButton size="sm" disabled={busy || index === 0} onClick={() => onMove(-1)}>↑</AppActionButton><AppActionButton size="sm" disabled={busy || index === itemCount - 1} onClick={() => onMove(1)}>↓</AppActionButton>{editing ? <AppActionButton size="sm" variant="primary" disabled={busy} onClick={() => void save()}>{language === 'zh' ? eventOperationsSurfacesText.save.zh : eventOperationsSurfacesText.save.en}</AppActionButton> : <AppActionButton size="sm" disabled={busy} onClick={() => setEditing(true)}>{language === 'zh' ? eventOperationsSurfacesText.edit.zh : eventOperationsSurfacesText.edit.en}</AppActionButton>}<AppActionButton size="sm" variant="danger" disabled={busy} onClick={() => void remove()}>{language === 'zh' ? eventOperationsSurfacesText.delete.zh : eventOperationsSurfacesText.delete.en}</AppActionButton></div> : null}</li>{confirmationModal}</>
}

const RosterTimeField = ({ label, value, language, className = '', onChange }: { label: string; value: string; language: 'en' | 'zh'; className?: string; onChange: (value: string) => void }) => {
  const parts = toTwelveHourTimeParts(value)
  const update = (patch: Partial<TwelveHourTimeParts>) => onChange(fromTwelveHourTimeParts({ ...parts, ...patch }))
  return <fieldset className={`min-w-0 ${className}`}><legend className="mb-1.5 text-xs font-bold uppercase tracking-[0.08em] text-[#66766f]">{label}</legend><div className="inline-grid max-w-full grid-cols-[3.25rem_auto_3.25rem_4.5rem] items-center gap-1"><select required aria-label={`${label} ${language === 'zh' ? eventOperationsSurfacesText.hour.zh : eventOperationsSurfacesText.hour.en}`} className={`${fieldClass} min-w-0 px-2`} value={parts.hour} onChange={(event) => update({ hour: event.target.value })}><option value="">--</option>{Array.from({ length: 12 }, (_, index) => index + 1).map((hour) => <option key={hour} value={hour}>{hour}</option>)}</select><span aria-hidden="true" className="font-black text-[#66766f]">:</span><select aria-label={`${label} ${language === 'zh' ? eventOperationsSurfacesText.minute.zh : eventOperationsSurfacesText.minute.en}`} className={`${fieldClass} min-w-0 px-2`} value={parts.minute} onChange={(event) => update({ minute: event.target.value })}>{Array.from({ length: 60 }, (_, minute) => String(minute).padStart(2, '0')).map((minute) => <option key={minute} value={minute}>{minute}</option>)}</select><select aria-label={`${label} ${language === 'zh' ? eventOperationsSurfacesText.period.zh : eventOperationsSurfacesText.period.en}`} className={`${fieldClass} min-w-0 px-2`} value={parts.period} onChange={(event) => update({ period: event.target.value as 'AM' | 'PM' })}><option value="AM">AM</option><option value="PM">PM</option></select></div></fieldset>
}

const RosterContext = createContext<ReturnType<typeof useRosterStore> | null>(null)
function useRosterStore(eventId: string, groupId: string) {
  const [occurrences, setOccurrences] = useState<EventOccurrence[]>([]), [occurrenceId, setOccurrenceId] = useState('')
  const [data, setData] = useState<EventRoster | null>(null), [team, setTeam] = useState<EventTeamWorkspace | null>(null)
  const [programme, setProgramme] = useState<EventProgramme | null>(null), [groups, setGroups] = useState<EventRosterGroup[]>([])
  const [candidates, setCandidates] = useState<MemberSummaryDto[]>([])
  const [state, setState] = useState<AsyncState>('loading'), [error, setError] = useState(''), [busy, setBusy] = useState(false)
  const loadRevision = useRef(0)
  useEffect(() => { let live = true; void eventOperationsService.listOccurrences(eventId).then(list => { if (live) { setOccurrences(list); setOccurrenceId(list.find(x => x.id === new URLSearchParams(window.location.search).get('occurrenceId'))?.id || list[0]?.id || '') } }).catch(reason => { if (live) { setState(resolveState(reason)); setError(normalizeApiError(reason).message) } }); return () => { live = false } }, [eventId])
  const load = useCallback(async () => {
    if (!occurrenceId) return
    const revision = ++loadRevision.current
    setState('loading'); setError('')
    try {
    const next = await eventOperationsService.getRoster(eventId, occurrenceId)
    const [nextTeam, memberships, nextProgramme, nextGroups] = await Promise.all([
      eventOperationsService.getTeam(eventId).catch(() => null),
      next.canManage ? groupService.getGroupMemberships(groupId) : Promise.resolve([]),
      eventOperationsService.getProgramme(eventId, occurrenceId).catch(() => null),
      next.canManage ? eventOperationsService.getRosterGroups(eventId) : Promise.resolve([]),
    ])
    if (revision !== loadRevision.current) return
    setData(next); setTeam(nextTeam); setProgramme(nextProgramme); setGroups(nextGroups)
    setCandidates(memberships.filter(x => x.status === 'approved').map(x => ({ id: x.memberId, displayName: x.displayName ?? null })))
    setState(next.slots.length ? 'ready' : 'empty')
    } catch (reason) {
      if (revision !== loadRevision.current) return
      setState(resolveState(reason)); setError(normalizeApiError(reason).message)
      throw reason
    }
  }, [eventId, groupId, occurrenceId])
  useEffect(() => { void load().catch(() => {}); return () => { loadRevision.current += 1 } }, [load])
  return { occurrences, occurrenceId, setOccurrenceId, data, setData, team, programme, groups, candidates, state, setState, error, setError, busy, setBusy, load }
}
function RosterProviderState({ eventId, groupId, children }: { eventId: string; groupId: string; children: ReactNode }) {
  const store = useRosterStore(eventId, groupId)
  return <RosterContext.Provider value={store}>{children}</RosterContext.Provider>
}
export function EventRosterProvider(props: { eventId: string; groupId: string; children: ReactNode }) {
  const viewer = useAuthStore().me?.id
  return <RosterProviderState key={`${props.eventId}:${viewer || ''}`} {...props} />
}
export const EventRosterWorkspace = (props: EventSurfaceProps & { rosterModule?: string }) => {
  const store = useContext(RosterContext)
  return store ? <RosterWorkspaceContent {...props} store={store} /> : <EventRosterProvider eventId={props.eventId} groupId={props.groupId}><EventRosterWorkspace {...props} /></EventRosterProvider>
}
const RosterWorkspaceContent = ({ eventId, language, item, onBusyChange, onSaved, rosterModule, store }: EventSurfaceProps & { rosterModule?: string; store: ReturnType<typeof useRosterStore> }) => {
  const currentMemberId = useAuthStore().me?.id
  const { occurrences, occurrenceId, setOccurrenceId, data: allData, setData, team, programme, groups, candidates, state, setState, error, setError, busy, setBusy, load } = store
  const data = allData ? { ...allData, slots: allData.slots.filter(slot => !rosterModule || (slot.moduleCode || 'SERVICE.ROSTER') === rosterModule), readinessBlockers: rosterModule ? [] : allData.readinessBlockers } : null
  const selectedOccurrence = occurrences.find(x => x.id === occurrenceId)
  const [roleCode, setRoleCode] = useState(''), [requiredCount, setRequiredCount] = useState(1), [start, setStart] = useState(''), [end, setEnd] = useState(''), [programItemId, setProgramItemId] = useState('')
  useArrangementDraft(Boolean(roleCode || requiredCount !== 1 || programItemId))
  useEffect(() => { if (selectedOccurrence) { setStart(localTimeValue(selectedOccurrence.startUtc)); setEnd(localTimeValue(selectedOccurrence.endUtc)) } }, [selectedOccurrence])
  useEffect(() => { onBusyChange?.(busy) }, [busy, onBusyChange])
  const mutate = async (action: () => Promise<EventRoster>) => { setBusy(true); setError(''); try { setData(await action()); await load(); setState('ready'); await onSaved?.() } catch (reason) { setState(resolveState(reason)); setError(normalizeApiError(reason).message) } finally { setBusy(false) } }
  const saveGroup = async (request: Omit<EventRosterGroup, 'eTag'>, eTag: string) => { setBusy(true); setError(''); try { await eventOperationsService.saveRosterGroup(eventId, request, eTag); await load(); await onSaved?.() } catch (reason) { setState(resolveState(reason)); setError(normalizeApiError(reason).message); throw reason } finally { setBusy(false) } }
  const selectedProgrammeItem = programme?.sessions.flatMap((session) => session.items.map((programmeItem) => ({ session, programmeItem }))).find((value) => value.programmeItem.id === programItemId)
  const create = (event: FormEvent) => { event.preventDefault(); if (!data || !selectedOccurrence) return; void mutate(async () => { if (!groups.some(g => g.roleCode === roleCode)) await eventOperationsService.saveRosterGroup(eventId, { roleCode, moduleCode: rosterModule || 'SERVICE.ROSTER', memberIds: [] }, '"new"'); const fresh = await eventOperationsService.getRoster(eventId, occurrenceId); const result = await eventOperationsService.createSlot(eventId, occurrenceId, fresh.eTag, { sessionId: selectedProgrammeItem?.session.id ?? null, programItemId: selectedProgrammeItem?.programmeItem.id ?? null, roleCode, requiredCount, startUtc: occurrenceLocalTimeToUtc(selectedOccurrence.startUtc, start), endUtc: occurrenceLocalTimeToUtc(selectedOccurrence.endUtc, end), eligibilityCode: 'approvedGroupMember' }); setRoleCode(''); setProgramItemId(''); await load(); return result }) }
  const content = <div className="space-y-4"><EventRosterBatchWorkspace eventId={eventId} language={language} moduleCode={rosterModule} onSaved={async () => { await load(); await onSaved?.() }} onBusyChange={onBusyChange} refreshVersion={data?.eTag} /><details className="rounded-xl border border-[#176b5a]/15 p-3"><summary className="min-h-11 cursor-pointer font-semibold">{language === 'zh' ? eventOperationsSurfacesText.positionSettingsAndPersonalAvailabilityByDate.zh : eventOperationsSurfacesText.positionSettingsAndPersonalAvailabilityByDate.en}</summary><AppSectionCard title={localize(item.label, language)} subtitle={language === 'zh' ? eventOperationsSurfacesText.createACandidateGroupForEachRoleThenAssign.zh : eventOperationsSurfacesText.createACandidateGroupForEachRoleThenAssign.en} action={<AppBadge variant={item.readiness === 'ready' ? 'success' : 'warning'}>{item.readiness}</AppBadge>}><label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.occurrenceLabel.zh : eventOperationsSurfacesText.occurrenceLabel.en}<select className={fieldClass} value={occurrenceId} disabled={busy} onChange={e => setOccurrenceId(e.target.value)}>{occurrences.map(x => <option key={x.id} value={x.id}>{formatLocalOccurrenceTime(x.startUtc, language)}</option>)}</select></label>{occurrenceId ? <div className="mt-4"><SurfaceState state={state} language={language} error={error} onRetry={() => void load()} /></div> : null}</AppSectionCard>{data?.readinessBlockers.length ? <AppSectionCard title={language === 'zh' ? eventOperationsSurfacesText.readinessGaps.zh : eventOperationsSurfacesText.readinessGaps.en}><ul className="space-y-2">{data.readinessBlockers.map((blocker, index) => <li key={`${blocker.en}-${index}`} className="rounded-xl border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-950">{localize(blocker, language)}</li>)}</ul></AppSectionCard> : null}{data?.canConfigure ? <details className="rounded-xl border border-[#176b5a]/15 p-3"><summary className="cursor-pointer font-semibold">{language === 'zh' ? eventOperationsSurfacesText.addRoleShift.zh : eventOperationsSurfacesText.addRoleShift.en}</summary><AppSectionCard title={language === 'zh' ? eventOperationsSurfacesText.addServiceSlot.zh : eventOperationsSurfacesText.addServiceSlot.en} subtitle={language === 'zh' ? eventOperationsSurfacesText.startAndEndInheritTheSelectedOccurrenceTheEvent.zh : eventOperationsSurfacesText.startAndEndInheritTheSelectedOccurrenceTheEvent.en}><form className="grid min-w-0 gap-3 tablet:grid-cols-2 desktop:grid-cols-12" onSubmit={create}><label className={`${labelClass} min-w-0 desktop:col-span-4`}>{language === 'zh' ? eventOperationsSurfacesText.roleCode.zh : eventOperationsSurfacesText.roleCode.en}<input className={fieldClass} value={roleCode} onChange={(event) => setRoleCode(event.target.value)} required /></label><label className={`${labelClass} min-w-0 desktop:col-span-6`}>{language === 'zh' ? eventOperationsSurfacesText.programmeItemOptional.zh : eventOperationsSurfacesText.programmeItemOptional.en}<select className={fieldClass} value={programItemId} onChange={(event) => setProgramItemId(event.target.value)}><option value="">{language === 'zh' ? eventOperationsSurfacesText.occurrenceWide.zh : eventOperationsSurfacesText.occurrenceWide.en}</option>{programme?.sessions.flatMap((session) => session.items.map((programmeItem) => <option key={programmeItem.id} value={programmeItem.id}>{localize(session.title, language)} · {localize(programmeItem.title, language)}</option>))}</select></label><label className={`${labelClass} w-24 max-w-full desktop:col-span-2`}>{language === 'zh' ? eventOperationsSurfacesText.people.zh : eventOperationsSurfacesText.people.en}<input type="number" min="1" className={`${fieldClass} w-24 max-w-full`} value={requiredCount} onChange={(event) => setRequiredCount(Number(event.target.value))} required /></label><RosterTimeField className="desktop:col-span-4" label={language === 'zh' ? eventOperationsSurfacesText.start.zh : eventOperationsSurfacesText.start.en} language={language} value={start} onChange={setStart} /><RosterTimeField className="desktop:col-span-4" label={language === 'zh' ? eventOperationsSurfacesText.end.zh : eventOperationsSurfacesText.end.en} language={language} value={end} onChange={setEnd} /><div className="flex items-end desktop:col-span-4"><AppActionButton type="submit" variant="primary" disabled={busy || !selectedOccurrence || !start || !end}>{language === 'zh' ? eventOperationsSurfacesText.addLabel.zh : eventOperationsSurfacesText.addLabel.en}</AppActionButton></div></form></AppSectionCard></details> : null}{data?.slots.map((slot) => <RosterSlot key={slot.id} data={data} slot={slot} team={team} candidates={candidates} currentMemberId={currentMemberId} language={language} busy={busy} onMutate={mutate} group={groups.find(g => g.roleCode === slot.roleCode)} onSaveGroup={saveGroup} />)}{data && !data.slots.length ? <AppEmptyState title={language === 'zh' ? eventOperationsSurfacesText.noServiceSlots.zh : eventOperationsSurfacesText.noServiceSlots.en} description={language === 'zh' ? eventOperationsSurfacesText.defineTheFirstSlotToTrackConfirmedVersusRequired.zh : eventOperationsSurfacesText.defineTheFirstSlotToTrackConfirmedVersusRequired.en} /> : null}</details></div>
  return rosterModule ? <AppSectionCard title={language === 'zh' ? eventOperationsSurfacesText.roleShifts.zh : eventOperationsSurfacesText.roleShifts.en} summary={surfaceStatusSummary(state, language) ?? (data ? (language === 'zh' ? eventOperationsSurfacesText.roleSlotsPeopleNeeded.zh(data.slots.length, data.slots.reduce((count, slot) => count + slot.requiredCount, 0)) : eventOperationsSurfacesText.roleSlotsPeopleNeeded.en(data.slots.length, data.slots.reduce((count, slot) => count + slot.requiredCount, 0))) : (language === 'zh' ? (state === 'loading' ? eventOperationsSurfacesText.rosterWorkspaceContent : eventOperationsSurfacesText.rosterWorkspaceContent2) : (state === 'loading' ? 'Loading shifts…' : 'Shift data unavailable')))}>{content}</AppSectionCard> : content
}

const RosterSlot = ({ data, slot, team, candidates, currentMemberId, language, busy, onMutate, group, onSaveGroup }: { group?: EventRosterGroup; onSaveGroup: (request: Omit<EventRosterGroup, 'eTag'>, eTag: string) => Promise<void>; data: EventRoster; slot: EventRoster['slots'][number]; team: EventTeamWorkspace | null; candidates: MemberSummaryDto[]; currentMemberId?: string; language: 'en' | 'zh'; busy: boolean; onMutate: (action: () => Promise<EventRoster>) => Promise<void> }) => {
  const [editing, setEditing] = useState(false); const [roleCode] = useState(slot.roleCode); const [requiredCount, setRequiredCount] = useState(slot.requiredCount)
  const { requestConfirmation, confirmationModal } = useConfirmation()
  useArrangementDraft(editing && requiredCount !== slot.requiredCount)
  const myAssignment = slot.assignments.find((assignment) => assignment.memberId === currentMemberId && assignment.status === 'invited')
  const remove = async () => { if (!await requestConfirmation({ title: language === 'zh' ? eventOperationsSurfacesText.deleteServiceSlot.zh : eventOperationsSurfacesText.deleteServiceSlot.en, description: language === 'zh' ? eventOperationsSurfacesText.allActiveAssignmentsMustBeEndedFirst.zh : eventOperationsSurfacesText.allActiveAssignmentsMustBeEndedFirst.en, tone: 'danger' })) return; await onMutate(() => eventOperationsService.deleteSlot(data.eventId, data.occurrenceId, slot.id, data.eTag)) }
  return <><AppSectionCard title={localize(slot.roleLabel ?? { en: slot.roleCode, zh: slot.roleCode }, language)} subtitle={`${slot.roleCode} · ${formatLocalOccurrenceTime(slot.startUtc, language)} – ${formatLocalTime(slot.endUtc, language)}`} action={<AppBadge variant={slot.confirmedCount >= slot.requiredCount ? 'success' : 'warning'}>{slot.confirmedCount}/{slot.requiredCount}</AppBadge>}>{data.canConfigure ? <div className="mb-4 flex flex-wrap gap-2">{editing ? <><input aria-label={language === 'zh' ? eventOperationsSurfacesText.role.zh : eventOperationsSurfacesText.role.en} className={fieldClass} value={roleCode} readOnly /><input className={`${fieldClass} max-w-28`} type="number" min="1" value={requiredCount} onChange={(event) => setRequiredCount(Number(event.target.value))} /><AppActionButton variant="primary" disabled={busy} onClick={() => void onMutate(() => eventOperationsService.updateSlot(data.eventId, data.occurrenceId, slot.id, data.eTag, { sessionId: slot.sessionId, programItemId: slot.programItemId, zoneId: slot.zoneId, roleCode, startUtc: slot.startUtc, endUtc: slot.endUtc, requiredCount, eligibilityCode: slot.eligibilityCode })).then(() => setEditing(false))}>{language === 'zh' ? eventOperationsSurfacesText.save.zh : eventOperationsSurfacesText.save.en}</AppActionButton></> : <AppActionButton disabled={busy} onClick={() => setEditing(true)}>{language === 'zh' ? eventOperationsSurfacesText.editSlot.zh : eventOperationsSurfacesText.editSlot.en}</AppActionButton>}<AppActionButton variant="danger" disabled={busy} onClick={() => void remove()}>{language === 'zh' ? eventOperationsSurfacesText.delete.zh : eventOperationsSurfacesText.delete.en}</AppActionButton></div> : null}{data.canConfigure ? <RosterCandidateGroup roleCode={slot.roleCode} moduleCode={slot.moduleCode || 'SERVICE.ROSTER'} group={group} candidates={candidates} language={language} busy={busy} onSave={onSaveGroup} /> : null}<div className="grid gap-4 tablet:grid-cols-2"><label className={labelClass}>{language === 'zh' ? eventOperationsSurfacesText.myAvailability.zh  : eventOperationsSurfacesText.myAvailability.en}<select className={fieldClass} value={slot.myAvailability ?? 'unknown'} disabled={busy || !slot.isRosterCandidate} onChange={(event) => void onMutate(() => eventOperationsService.setAvailability(data.eventId, data.occurrenceId, slot.id, event.target.value as 'unknown' | 'available' | 'unavailable' | 'preferNot'))}><option value="unknown">unknown</option><option value="available">available</option><option value="preferNot">preferNot</option><option value="unavailable">unavailable</option></select></label>{myAssignment ? <div className="flex items-end gap-2"><AppActionButton variant="primary" disabled={busy} onClick={() => void onMutate(() => eventOperationsService.respondToRosterAssignment(data.eventId, data.occurrenceId, myAssignment.id, true))}>{language === 'zh' ? eventOperationsSurfacesText.confirm.zh : eventOperationsSurfacesText.confirm.en}</AppActionButton><AppActionButton disabled={busy} onClick={() => void onMutate(() => eventOperationsService.respondToRosterAssignment(data.eventId, data.occurrenceId, myAssignment.id, false))}>{language === 'zh' ? eventOperationsSurfacesText.declineLabel.zh : eventOperationsSurfacesText.declineLabel.en}</AppActionButton></div> : null}</div>{slot.assignments.length ? <ul className="mt-4 space-y-2">{slot.assignments.map((assignment) => <li key={assignment.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-[#eef4ef] px-3 py-2 text-sm"><span>{candidates.find((candidate) => candidate.id === assignment.memberId)?.displayName || team?.members.find((member) => member.memberId === assignment.memberId)?.displayName || assignment.memberId}</span><div className="flex items-center gap-2"><AppBadge variant={assignment.status === 'confirmed' ? 'success' : assignment.status === 'declined' ? 'danger' : 'warning'}>{assignment.status}</AppBadge></div></li>)}</ul> : null}</AppSectionCard>{confirmationModal}</>
}
